import{_ as t,d as a,e as o,y as i}from"./chunks/framework.D7CAgLCq.js";const u=JSON.parse('{"title":"Doing the work does not settle all responsibility","description":"Keep uptake, costs, benefits, control, and justified duties distinct.","frontmatter":{"title":"Doing the work does not settle all responsibility","description":"Keep uptake, costs, benefits, control, and justified duties distinct."},"headers":[],"relativePath":"en/concepts/responsibility.md","filePath":"en/concepts/responsibility.md"}'),s={name:"en/concepts/responsibility.md"};function n(r,e,l,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="doing-the-work-does-not-settle-all-responsibility" tabindex="-1">Doing the work does not settle all responsibility <a class="header-anchor" href="#doing-the-work-does-not-settle-all-responsibility" aria-label="Permalink to &quot;Doing the work does not settle all responsibility&quot;">​</a></h1><p>An <strong>uptake carrier (CV)</strong> executes, transmits, maintains, records, cares for, or repairs something. It may be a person, role, procedure, facility, or technical system. A <strong>responsible party (RS)</strong> is identified through an independent basis for a particular kind, scope, and period of responsibility.</p><h2 id="follow-both-the-work-and-the-authority" tabindex="-1">Follow both the work and the authority <a class="header-anchor" href="#follow-both-the-work-and-the-authority" aria-label="Permalink to &quot;Follow both the work and the authority&quot;">​</a></h2><p>The most visible worker may have little control over staffing, deadlines, budgets, or system design. Recording that worker’s actual action remains important, but does not make them the default bearer of every upstream and downstream duty. A facility can carry a signal without becoming a moral or legal subject. Organizational responsibility, where applicable, depends on its own rules and standing.</p><p>The framework asks analysts to separate action, decision, authorization, supervision, benefit, and remedy. These roles can coincide, but that must be established rather than assumed. Knowledge, control, applicable duties, available alternatives, and the relevant period matter to the judgment.</p><p>Costs, beneficiaries, and the right to stop are separate too. The fact that someone can absorb more work does not create an unlimited duty to do so. A recommendation to redistribute work still needs an appropriate normative basis and valid authorization before execution.</p><h2 id="use-a-concrete-question" tabindex="-1">Use a concrete question <a class="header-anchor" href="#use-a-concrete-question" aria-label="Permalink to &quot;Use a concrete question&quot;">​</a></h2><p>In a hypothetical service team, one employee performs urgent repairs while another role sets the maintenance budget. To assess the employee’s conduct, examine what they knew and controlled. To assess preventive or remedial duties, examine the budget decision, supervision, organizational commitments, and applicable rules. “The system caused it” and “the last person touched it” are both incomplete substitutes for that inquiry.</p><p>The <a href="./../cases/mars-climate-orbiter.html">Mars Climate Orbiter report</a> documents an interface failure and contributing factors; the case page does not infer all legal or moral responsibility from who produced or read a file. The <a href="./../cases/atlantic-archives-exit.html">Atlantic archives case</a> distinguishes custody of records from responsibility for an institution’s remaining obligations.</p><h2 id="the-boundary-of-this-distinction" tabindex="-1">The boundary of this distinction <a class="header-anchor" href="#the-boundary-of-this-distinction" aria-label="Permalink to &quot;The boundary of this distinction&quot;">​</a></h2><p>CV and RS are analytical categories. Naming them does not decide a real dispute, assign liability, or grant authority to change a person’s work. Nor does distinguishing responsibility erase an independently supported account of harm or a practical need for protection.</p><p>Read <a href="/xi-kari-skill/handbook/en/theory/part-02.html#section-2-8">§2.8</a>, <a href="/xi-kari-skill/handbook/en/theory/part-07.html#section-7-2-4">§7.2.4</a>, <a href="/xi-kari-skill/handbook/en/theory/part-07.html#section-7-2-5">§7.2.5</a>, and <a href="/xi-kari-skill/handbook/en/theory/appendix-a/a-05.html#section-a-5">A.5</a>.</p>',12)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
